trait Container {
    type Item;
    fn push(&mut self, item: Self);
    fn pop(&mut self) -> Option<Self>;
}

struct Stack {
    inner: Vec<i32>,
}

impl Container for Stack {
    type Item = i32;
    fn push(&mut self, item: i32) {
        self.inner.push(item);
    }
    fn pop(&mut self) -> Option<i32> {
        self.inner.pop()
    }
}

fn main() {
    let mut s = Stack { inner: vec![] };
    s.push(1);
    s.push(2);
    println!("{:?}", s.pop());
}
